CREATE TABLE IF NOT EXISTS `news` (  `news_id` int(11) NOT NULL AUTO_INCREMENT,  `enabled` tinyint(1) NOT NULL,  `header` varchar(255) NOT NULL,  `url` varchar(255) NOT NULL,  `date` date NOT NULL,  `meta_title` varchar(255) NOT NULL,  `meta_keywords` varchar(255) NOT NULL,  `meta_description` varchar(255) NOT NULL,  `body` text NOT NULL,  `image` varchar(255) NOT NULL,  `editor_id` int(11) NOT NULL,  `created` date NOT NULL,  `modified` date NOT NULL,  PRIMARY KEY (`news_id`),  UNIQUE KEY `url` (`url`)) ENGINE=MyISAM  DEFAULT CHARSET=utf8 AUTO_INCREMENT=1 ;